export interface ConnectorConfig {
  hubspotAccessToken: string
  fetch?: typeof fetch
}

export interface StripeCheckoutSessionCompleted {
  id: string
  object: 'checkout.session'
  customer_email: string
  client_reference_id?: string
}

export interface HubSpotContactResponse {
  vid: number
  isNew: boolean
}

export interface HandleResult {
  hubspotContactId: number
  isNewContact: boolean
  stripeSessionId: string
}

export async function handle(
  payload: StripeCheckoutSessionCompleted,
  config: ConnectorConfig
): Promise<HandleResult> {
  const fetchImpl = config.fetch ?? fetch

  if (!payload.id) {
    throw new Error('Missing required field: id (Stripe session id)')
  }
  if (!payload.customer_email) {
    throw new Error('Missing required field: customer_email')
  }

  const encodedEmail = encodeURIComponent(payload.customer_email)
  const url = `https://api.hubapi.com/contacts/v1/contact/createOrUpdate/email/${encodedEmail}`

  const body = {
    properties: [
      {
        property: 'email',
        value: payload.customer_email
      }
    ]
  }

  const headers: Record<string, string> = {
    'Authorization': `Bearer ${config.hubspotAccessToken}`,
    'Content-Type': 'application/json',
    'Idempotency-Key': payload.id
  }

  const response = await fetchImpl(url, {
    method: 'POST',
    headers,
    body: JSON.stringify(body)
  })

  if (!response.ok) {
    throw new Error(`HubSpot API error: ${response.status} ${response.statusText} for POST ${url}`)
  }

  const result = await response.json() as HubSpotContactResponse

  return {
    hubspotContactId: result.vid,
    isNewContact: result.isNew,
    stripeSessionId: payload.id
  }
}

import { describe, it, expect, vi } from 'vitest'
import { handle, StripeCheckoutSessionCompleted, ConnectorConfig } from './connector'
import { SOURCE_EXAMPLE, contractFetch, fakeFetch, jsonResponse, TARGET_ENDPOINTS } from './fixtures'

describe('contract', () => {
  it('handles the documented example payload', async () => {
    const { fetch, calls } = contractFetch()
    const config: ConnectorConfig = {
      hubspotAccessToken: 'test-access-token',
      fetch
    }
    const result = await handle(SOURCE_EXAMPLE as unknown as StripeCheckoutSessionCompleted, config)
    expect(calls.length).toBeGreaterThan(0)
    expect(result.hubspotContactId).toBe(3234574)
    expect(result.isNewContact).toBe(false)
    expect(result.stripeSessionId).toBe(SOURCE_EXAMPLE.id)
  })
})

describe('handle', () => {
  it('maps customer_email to HubSpot email property and sends Idempotency-Key', async () => {
    const { fetch, calls } = fakeFetch((req) => {
      expect(req.method).toBe('POST')
      expect(req.url).toBe('https://api.hubapi.com/contacts/v1/contact/createOrUpdate/email/customer%40example.com')
      expect(req.json).toEqual({
        properties: [{ property: 'email', value: 'customer@example.com' }]
      })
      expect(req.headers.get('authorization')).toBe('Bearer test-token')
      expect(req.headers.get('idempotency-key')).toBe('cs_test_123')
      return jsonResponse({ vid: 98765, isNew: true })
    })

    const payload: StripeCheckoutSessionCompleted = {
      id: 'cs_test_123',
      object: 'checkout.session',
      customer_email: 'customer@example.com'
    }

    const result = await handle(payload, { hubspotAccessToken: 'test-token', fetch })
    expect(result.hubspotContactId).toBe(98765)
    expect(result.isNewContact).toBe(true)
    expect(result.stripeSessionId).toBe('cs_test_123')
  })

  it('throws when customer_email is missing', async () => {
    const { fetch } = fakeFetch(() => jsonResponse({}, 200))
    const payload = { id: 'cs_test_123', object: 'checkout.session' as const } as unknown as StripeCheckoutSessionCompleted
    await expect(handle(payload, { hubspotAccessToken: 'test-token', fetch })).rejects.toThrow('Missing required field: customer_email')
  })

  it('throws when id is missing', async () => {
    const { fetch } = fakeFetch(() => jsonResponse({}, 200))
    const payload = { customer_email: 'test@example.com', object: 'checkout.session' as const } as unknown as StripeCheckoutSessionCompleted
    await expect(handle(payload, { hubspotAccessToken: 'test-token', fetch })).rejects.toThrow('Missing required field: id')
  })

  it('throws on non-2xx HubSpot response with status and endpoint', async () => {
    const { fetch } = fakeFetch(() => jsonResponse({ error: 'unauthorized' }, 401))
    const payload: StripeCheckoutSessionCompleted = {
      id: 'cs_test_123',
      object: 'checkout.session',
      customer_email: 'customer@example.com'
    }
    await expect(handle(payload, { hubspotAccessToken: 'test-token', fetch })).rejects.toThrow('HubSpot API error: 401 Unauthorized for POST https://api.hubapi.com/contacts/v1/contact/createOrUpdate/email/customer%40example.com')
  })

  it('URL-encodes email with special characters', async () => {
    const { fetch, calls } = fakeFetch((req) => {
      expect(req.url).toBe('https://api.hubapi.com/contacts/v1/contact/createOrUpdate/email/test%2Btag%40example.com')
      return jsonResponse({ vid: 111, isNew: false })
    })

    const payload: StripeCheckoutSessionCompleted = {
      id: 'cs_test_456',
      object: 'checkout.session',
      customer_email: 'test+tag@example.com'
    }

    await handle(payload, { hubspotAccessToken: 'test-token', fetch })
    expect(calls[0].url).toContain('test%2Btag%40example.com')
  })
})

